schema:
CREATE TABLE DEPTS (
    DNAME INTEGER,
    DPROJ INTEGER
);
CREATE TABLE PAYROLL (
    EMPL  INTEGER PRIMARY KEY,
    PDEPT INTEGER
);
CREATE TABLE TEAMS (
    TMEMBER INTEGER,
    TPROJ   INTEGER,
    FOREIGN KEY (TMEMBER) REFERENCES PAYROLL(EMPL)
);

counterexample:
INSERT INTO DEPTS (DNAME, DPROJ) VALUES (100, 1);
INSERT INTO DEPTS (DNAME, DPROJ) VALUES (200, 2);
INSERT INTO DEPTS (DNAME, DPROJ) VALUES (300, 3);
-- SECURITY department
INSERT INTO DEPTS (DNAME, DPROJ) VALUES ('SECURITY', 4);

INSERT INTO PAYROLL (EMPL, PDEPT) VALUES (10, 200);
INSERT INTO PAYROLL (EMPL, PDEPT) VALUES (20, 100);
INSERT INTO PAYROLL (EMPL, PDEPT) VALUES (30, 'SECURITY');
INSERT INTO PAYROLL (EMPL, PDEPT) VALUES (40, 300);

-- TMEMBER in a different department
INSERT INTO TEAMS (TMEMBER, TPROJ) VALUES (10, 4);
-- Correct department, but employee is not in the project
INSERT INTO TEAMS (TMEMBER, TPROJ) VALUES (30, 3);
-- Correct department and project, but no link in PAYROLL
INSERT INTO TEAMS (TMEMBER, TPROJ) VALUES (20, 4);
-- Misleading correct setup with wrong employee in PAYROLL
INSERT INTO TEAMS (TMEMBER, TPROJ) VALUES (40, 4);

